import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(address actor, uint256 unlockTime, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c) && actor.code.length == 0);
        amount = bound(amount, 1 ether, 100 ether);
        // pick a strictly past unlock time so the clamp is the deciding factor
        unlockTime = bound(unlockTime, 0, block.timestamp - 1);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // Collect the whole balance immediately: must be impossible since
        // unlockTime >= block.timestamp after any Put.
        vm.prank(actor);
        try c.Collect(amount) {
            // if it succeeded the balance was drained
        } catch {
            // reference behaviour: revert
        }

        assertTrue(c.Acc(actor).balance == amount, "balance must remain after immediate Collect");
    }
}

