pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 unlockTime, uint256 amount, address actor) public {
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        amount = bound(amount, 1 ether, 100 ether);
        // past (or equal-to-now) unlock times are exactly where the clamp matters
        vm.assume(unlockTime <= block.timestamp);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // Rule: right after any Put, an immediate Collect of any amount must fail,
        // because the stored unlockTime is clamped to at least the current timestamp.
        vm.prank(actor);
        bool ok;
        try c.Collect(amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "Collect must fail immediately after Put (unlockTime is clamped to now)");
    }
}

