pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        amount = bound(amount, 1, 10 ether);

        (,,,, uint lenBefore) = c.LogFile().History(0);
        // History is a public array getter; instead read length via helper below.

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        // General rule: a successful Put logs a message from the caller with the deposited value,
        // so the last History entry matches (actor, amount).
        (address sender, string memory, uint val, uint) = c.LogFile().History(0);
        assertTrue(sender == actor && val == amount);
    }
}

