pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;
    function setUp() public { log = new Log(); c = new C(address(log)); }
    function testFuzz_property(address actor, uint64 amount, uint8 callsRaw) public {
        vm.assume(actor != address(0) && actor != address(c));
        uint256 amountB = bound(uint256(amount), 1, 1 ether);
        uint256 calls = bound(uint256(callsRaw), 1, 5);
        vm.deal(actor, amountB * calls);
        for (uint256 i = 0; i < calls; i++) {
            vm.prank(actor);
            c.Put{value: amountB}(0);
        }
        bool recorded;
        try log.History(calls - 1) returns (address, string memory, uint256, uint256) {
            recorded = true;
        } catch {
            recorded = false;
        }
        assertTrue(recorded, "every deposit must be logged in History");
    }
}

