pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log logC;

    function setUp() public {
        logC = new Log();
        c = new C(address(logC));
    }

    function testFuzz_property(address actor1, address actor2, uint256 amount1, uint256 amount2) public {
        vm.assume(actor1 != address(0) && actor2 != address(0));
        vm.assume(actor1 != address(c) && actor2 != address(c));
        vm.assume(actor1 != actor2);
        amount1 = bound(amount1, 1, 1e30);
        amount2 = bound(amount2, 1, 1e30);

        vm.deal(actor1, amount1);
        vm.prank(actor1);
        c.Put{value: amount1}(0);

        vm.deal(actor2, amount2);
        vm.prank(actor2);
        c.Put{value: amount2}(0);

        (bool ok0, bytes memory ret0) =
            address(logC).staticcall(abi.encodeWithSelector(Log.History.selector, 0));
        (bool ok1, bytes memory ret1) =
            address(logC).staticcall(abi.encodeWithSelector(Log.History.selector, 1));

        uint256 val0 = 0;
        uint256 val1 = 0;
        if (ok0) {
            (, , uint256 v0, ) = abi.decode(ret0, (address, string, uint256, uint256));
            val0 = v0;
        }
        if (ok1) {
            (, , uint256 v1, ) = abi.decode(ret1, (address, string, uint256, uint256));
            val1 = v1;
        }

        assertTrue(
            ok0 && ok1 && val0 == amount1 && val1 == amount2,
            "each Put must log exactly one History entry with its own amount"
        );
    }
}

