pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log lg;
    bytes4 constant HIST_SEL = bytes4(keccak256("History(uint256)"));

    function setUp() public {
        lg = new Log();
        c = new C(address(lg));
    }

    function testFuzz_property(uint256 amount, uint256 warpTime, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(lg));
        amount = bound(amount, 1, 100 ether);
        warpTime = bound(warpTime, block.timestamp + 1, block.timestamp + 365 days);

        vm.deal(actor, amount);
        vm.warp(warpTime);
        vm.prank(actor);
        c.Put{value: amount}(warpTime + 1 hours);

        // The log must contain an entry stamped with this exact deposit time,
        // crediting this exact actor and amount.
        (bool ok, bytes memory ret) = address(lg).staticcall(abi.encodeWithSelector(HIST_SEL, 0));
        bool recorded = false;
        if (ok && ret.length >= 32 * 4) {
            (address s, , uint256 v, uint256 t) = abi.decode(ret, (address, string, uint256, uint256));
            recorded = (s == actor && v == amount && t == warpTime);
        }
        assertTrue(recorded);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentLog lg;

    function setUp() public {
        lg = new ReentLog();
        c = new C(address(lg));
        lg.setTarget(address(c));
    }

    function testFuzz_property(uint256 amount, uint256 rv, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(lg));
        amount = bound(amount, 1, 1e30);
        rv = bound(rv, 1, 1e30);

        // Actor deposits `amount` via Put; Put's execution externally calls Log.AddMessage,
        // during which the Log helper re-enters c.Put with value `rv` (armed exactly once).
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(block.timestamp + 1);

        vm.deal(address(lg), rv);
        vm.prank(actor);
        c.Put{value: 0}(block.timestamp);

        // Rule: once a Put triggered by `actor` completes, the re-entrant Put launched by the
        // Log contract while the lock is held must have been rejected, so the recorded balance
        // of `actor` is exactly the value he deposited. The mutant credits the re-entrant value.
        assertTrue(c.Acc(actor).balance == amount);
    }
}

// Adversarial counterparty: c's Put always performs an external call into its Log contract;
// this helper plays that Log and re-enters c.Put while Put is still executing.
contract ReentLog {
    address target;
    bool armed = true;
    uint256 reVal;

    function setTarget(address t) external {
        target = t;
    }

    // value sent with the second (outer) Put funds the re-entrant call
    function AddMessage(address, uint256, string calldata) external payable {
        if (armed && target != address(0)) {
            reVal = msg.value; // outer Put sent 0; use the deal'ed balance instead
            reVal = address(this).balance;
            armed = false;
            (bool s, ) = target.call{value: reVal}(abi.encodeWithSignature("Put(uint256)", uint256(0)));
            s; // low-level: do not propagate the (correct) revert
        }
    }

    receive() external payable {}
}
